"""
Tic Tac Toe Player
"""

import copy

X = "X"
O = "O"
EMPTY = None


def initial_state():
    """Returns starting state of the board."""
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]


def player(board):
    """Returns player who has the next turn on a board."""
    x = sum(row.count(X) for row in board)
    o = sum(row.count(O) for row in board)
    return X if x == o else O


def actions(board):
    """Returns set of all possible actions (i, j) available on the board."""
    return {(i, j) for i in range(3) for j in range(3) if board[i][j] is EMPTY}


def result(board, action):
    """Returns the board that results from making move (i, j) on the board."""
    i, j = action
    if action not in actions(board):
        raise ValueError("invalid action")
    new = copy.deepcopy(board)
    new[i][j] = player(board)
    return new


LINES = [[(i, 0), (i, 1), (i, 2)] for i in range(3)] + \
        [[(0, j), (1, j), (2, j)] for j in range(3)] + \
        [[(0, 0), (1, 1), (2, 2)], [(0, 2), (1, 1), (2, 0)]]


def winner(board):
    """Returns the winner of the game, if there is one."""
    for line in LINES:
        a, b, c = (board[i][j] for i, j in line)
        if a is not EMPTY and a == b == c:
            return a
    return None


def terminal(board):
    """Returns True if game is over, False otherwise."""
    return winner(board) is not None or not actions(board)


def utility(board):
    """Returns 1 if X has won the game, -1 if O has won, 0 otherwise."""
    w = winner(board)
    return 1 if w == X else -1 if w == O else 0


def minimax(board):
    """Returns the optimal action for the current player on the board."""
    if terminal(board):
        return None

    def max_value(b):
        if terminal(b):
            return utility(b)
        v = -2
        for a in actions(b):
            v = max(v, min_value(result(b, a)))
        return v

    def min_value(b):
        if terminal(b):
            return utility(b)
        v = 2
        for a in actions(b):
            v = min(v, max_value(result(b, a)))
        return v

    best = None
    if player(board) == X:
        bv = -2
        for a in sorted(actions(board)):
            v = min_value(result(board, a))
            if v > bv:
                bv, best = v, a
    else:
        bv = 2
        for a in sorted(actions(board)):
            v = max_value(result(board, a))
            if v < bv:
                bv, best = v, a
    return best

