PROBS = {
    "gene": {2: 0.01, 1: 0.03, 0: 0.96},
    "trait": {
        2: {True: 0.65, False: 0.35},
        1: {True: 0.56, False: 0.44},
        0: {True: 0.01, False: 0.99},
    },
    "mutation": 0.01,
}


def joint_probability(people, one_gene, two_genes, have_trait):
    def genes(p):
        return 2 if p in two_genes else 1 if p in one_gene else 0

    def passes(parent):
        g = genes(parent)
        if g == 0:
            return PROBS["mutation"]
        if g == 1:
            return 0.5
        return 1 - PROBS["mutation"]

    total = 1
    for person in people:
        g = genes(person)
        mother, father = people[person]["mother"], people[person]["father"]
        if mother is None and father is None:
            p = PROBS["gene"][g]
        else:
            m, f = passes(mother), passes(father)
            if g == 2:
                p = m * f
            elif g == 1:
                p = m * (1 - f) + (1 - m) * f
            else:
                p = (1 - m) * (1 - f)
        total *= p * PROBS["trait"][g][person in have_trait]
    return total


def update(probabilities, one_gene, two_genes, have_trait, p):
    for person in probabilities:
        g = 2 if person in two_genes else 1 if person in one_gene else 0
        probabilities[person]["gene"][g] += p
        probabilities[person]["trait"][person in have_trait] += p


def normalize(probabilities):
    for person in probabilities:
        for field in ("gene", "trait"):
            total = sum(probabilities[person][field].values())
            for v in probabilities[person][field]:
                probabilities[person][field][v] /= total

