import random

DAMPING = 0.85
SAMPLES = 10000


def transition_model(corpus, page, damping_factor):
    n = len(corpus)
    links = corpus[page]
    dist = {p: (1 - damping_factor) / n for p in corpus}
    if links:
        for link in links:
            dist[link] += damping_factor / len(links)
    else:
        for p in dist:
            dist[p] += damping_factor / n
    return dist


def sample_pagerank(corpus, damping_factor, n):
    counts = {p: 0 for p in corpus}
    page = random.choice(list(corpus))
    counts[page] += 1
    for _ in range(n - 1):
        dist = transition_model(corpus, page, damping_factor)
        page = random.choices(list(dist), weights=list(dist.values()))[0]
        counts[page] += 1
    return {p: c / n for p, c in counts.items()}


def iterate_pagerank(corpus, damping_factor):
    n = len(corpus)
    rank = {p: 1 / n for p in corpus}
    while True:
        new = {}
        for p in corpus:
            total = 0
            for i in corpus:
                links = corpus[i]
                if not links:
                    total += rank[i] / n
                elif p in links:
                    total += rank[i] / len(links)
            new[p] = (1 - damping_factor) / n + damping_factor * total
        done = all(abs(new[p] - rank[p]) <= 0.001 for p in corpus)
        rank = new
        if done:
            return rank

