import sys

from crossword import *


class CrosswordCreator():

    def __init__(self, crossword):
        """
        Create new CSP crossword generate.
        """
        self.crossword = crossword
        self.domains = {
            var: self.crossword.words.copy()
            for var in self.crossword.variables
        }

    def letter_grid(self, assignment):
        """
        Return 2D array representing a given assignment.
        """
        letters = [
            [None for _ in range(self.crossword.width)]
            for _ in range(self.crossword.height)
        ]
        for variable, word in assignment.items():
            direction = variable.direction
            for k in range(len(word)):
                i = variable.i + (k if direction == Variable.DOWN else 0)
                j = variable.j + (k if direction == Variable.ACROSS else 0)
                letters[i][j] = word[k]
        return letters

    def print(self, assignment):
        """
        Print crossword assignment to the terminal.
        """
        letters = self.letter_grid(assignment)
        for i in range(self.crossword.height):
            for j in range(self.crossword.width):
                if self.crossword.structure[i][j]:
                    print(letters[i][j] or " ", end="")
                else:
                    print("█", end="")
            print()

    def save(self, assignment, filename):
        """Суретке сақтау (Pillow қажет; браузерде керек емес)."""
        raise NotImplementedError

    def solve(self):
        """
        Enforce node and arc consistency, and then solve the CSP.
        """
        self.enforce_node_consistency()
        self.ac3()
        return self.backtrack(dict())

    def enforce_node_consistency(self):
        for var in self.crossword.variables:
            self.domains[var] = {
                w for w in self.domains[var] if len(w) == var.length
            }

    def revise(self, x, y):
        overlap = self.crossword.overlaps[x, y]
        if overlap is None:
            return False
        i, j = overlap
        revised = False
        for word in list(self.domains[x]):
            if not any(word[i] == other[j] for other in self.domains[y]):
                self.domains[x].remove(word)
                revised = True
        return revised

    def ac3(self, arcs=None):
        if arcs is None:
            queue = [
                (x, y)
                for x in self.crossword.variables
                for y in self.crossword.neighbors(x)
            ]
        else:
            queue = list(arcs)
        while queue:
            x, y = queue.pop(0)
            if self.revise(x, y):
                if not self.domains[x]:
                    return False
                for z in self.crossword.neighbors(x) - {y}:
                    queue.append((z, x))
        return True

    def assignment_complete(self, assignment):
        return all(
            var in assignment and assignment[var]
            for var in self.crossword.variables
        )

    def consistent(self, assignment):
        words = list(assignment.values())
        if len(words) != len(set(words)):
            return False
        for var, word in assignment.items():
            if len(word) != var.length:
                return False
            for other in self.crossword.neighbors(var):
                if other in assignment:
                    i, j = self.crossword.overlaps[var, other]
                    if word[i] != assignment[other][j]:
                        return False
        return True

    def order_domain_values(self, var, assignment):
        def ruled_out(word):
            n = 0
            for other in self.crossword.neighbors(var):
                if other in assignment:
                    continue
                i, j = self.crossword.overlaps[var, other]
                n += sum(1 for w in self.domains[other] if w[j] != word[i])
            return n
        return sorted(self.domains[var], key=ruled_out)

    def select_unassigned_variable(self, assignment):
        unassigned = [v for v in self.crossword.variables if v not in assignment]
        return min(
            unassigned,
            key=lambda v: (len(self.domains[v]), -len(self.crossword.neighbors(v)))
        )

    def backtrack(self, assignment):
        if self.assignment_complete(assignment):
            return assignment
        var = self.select_unassigned_variable(assignment)
        for value in self.order_domain_values(var, assignment):
            assignment[var] = value
            if self.consistent(assignment):
                result = self.backtrack(assignment)
                if result is not None:
                    return result
            del assignment[var]
        return None

def main():

    # Check usage
    if len(sys.argv) not in [3, 4]:
        sys.exit("Usage: python generate.py structure words [output]")

    # Parse command-line arguments
    structure = sys.argv[1]
    words = sys.argv[2]
    output = sys.argv[3] if len(sys.argv) == 4 else None

    # Generate crossword
    crossword = Crossword(structure, words)
    creator = CrosswordCreator(crossword)
    assignment = creator.solve()

    # Print result
    if assignment is None:
        print("No solution.")
    else:
        creator.print(assignment)
        if output:
            creator.save(assignment, output)


if __name__ == "__main__" and len(sys.argv) > 1:
    main()

