def sigmoid(z):
    return 1 / (1 + math.exp(-z))


def neuron(weights, bias, inputs):
    z = bias
    for w, x in zip(weights, inputs):
        z += w * x
    return sigmoid(z)


def train_step(weights, bias, inputs, target, rate):
    error = neuron(weights, bias, inputs) - target
    new_weights = [w - rate * error * x for w, x in zip(weights, inputs)]
