import math


def cosine(a, b):
    if len(a) != len(b):
        raise ValueError("ұзындықтары әртүрлі")
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        raise ValueError("нөлдік вектор")
    return sum(x * y for x, y in zip(a, b)) / (na * nb)


def most_similar(word, vectors):
    best, best_score = None, -2
    for other, vec in vectors.items():
        if other == word:
            continue
        score = cosine(vectors[word], vec)
        if score > best_score:
            best, best_score = other, score
    return best

