def resolve(path, urlpatterns):
    parts = path.strip("/").split("/") if path.strip("/") else []
    for route, name in urlpatterns:
        pat = route.strip("/").split("/") if route.strip("/") else []
        if len(pat) != len(parts):
            continue
        kwargs = {}
        ok = True
        for p, s in zip(pat, parts):
            if p.startswith("<") and p.endswith(">"):
                kind, var = p[1:-1].split(":")
                if kind == "int":
                    if not s.isdigit():
                        ok = False
                        break
                    kwargs[var] = int(s)
                else:
                    if s == "":
                        ok = False
                        break
                    kwargs[var] = s
            elif p != s:
                ok = False
                break
        if ok:
            return (name, kwargs)
    return None

