        """Squares of primes are not prime."""
        for n in (4, 9, 25, 49, 121):
            self.assertFalse(is_prime(n), n)

    def test_primes(self):
        """Some primes."""
        for n in (3, 5, 7, 11, 13, 97, 101):
            self.assertTrue(is_prime(n), n)

